# Fetch all pending Venmo received payment requests and filter by roommate/coworker sender email

page_index = 0
page_limit = 20
pending_requests = []

while True:
    resp = apis.venmo.show_received_payment_requests(access_token=venmo_token, query='', status='pending', page_index=page_index, page_limit=page_limit)
    print('page_index', page_index, 'resp_type', type(resp), 'len', (len(resp) if isinstance(resp, list) else None))
    if not resp:
        break
    if isinstance(resp, list):
        pending_requests.extend(resp)
        if len(resp) < page_limit:
            break
    else:
        # Unexpected
        break
    page_index += 1

print('total_pending_requests:', len(pending_requests))

relevant_emails = all_relevant_emails

eligible = []
for pr in pending_requests:
    sender_email = None
    if isinstance(pr, dict):
        sender = pr.get('sender') or {}
        sender_email = sender.get('email')
    if sender_email and sender_email in relevant_emails:
        eligible.append(pr)

print('eligible_count:', len(eligible))
print('eligible_ids:', [e['payment_request_id'] for e in eligible])
print('eligible_details:', [
    {
        'id': e['payment_request_id'],
        'amount': e.get('amount'),
        'sender': (e.get('sender') or {}).get('email'),
        'desc': e.get('description'),
        'created_at': e.get('created_at')
    } for e in eligible
])

# Also print non-eligible senders for verification
non_eligible = []
for pr in pending_requests:
    sender_email = (pr.get('sender') or {}).get('email')
    if not (sender_email and sender_email in relevant_emails):
        non_eligible.append(pr)

print('non_eligible_count:', len(non_eligible))
print('non_eligible_sample:', [
    {
        'id': pr['payment_request_id'],
        'amount': pr.get('amount'),
        'sender': (pr.get('sender') or {}).get('email'),
        'created_at': pr.get('created_at')
    } for pr in non_eligible[:10]
])

